import { screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { graphql, HttpResponse } from 'msw';
import { describe, expect, it } from 'vitest';
import type { PropertiesQuery, PropertiesQueryVariables } from '@/gql/graphql';
import { server } from '@/test/msw';
import { renderRoute } from '@/test/render';

type Property = PropertiesQuery['properties'][number];

const property = (street: string, city: string, state: Property['state'], zipCode: string) =>
  ({
    __typename: 'Property',
    id: `id-${street}`,
    street,
    city,
    state,
    zipCode,
    createdAt: '2026-09-24T10:53:08.106Z',
    weatherData: {
      __typename: 'Weather',
      temperature: 79,
      weatherDescriptions: ['Overcast'],
      weatherIcons: [],
    },
  }) satisfies Property;

const ROWS = [
  property('15528 E Golden Eagle Blvd', 'Fountain Hills', 'AZ', '85268'),
  property('1 Main St', 'San Juan', 'PR', '00901'),
];

/** A tiny stand-in for the server's S3 semantics, recording every request's variables. */
function serveFiltered(calls: PropertiesQueryVariables[]) {
  return graphql.query<PropertiesQuery, PropertiesQueryVariables>('Properties', ({ variables }) => {
    calls.push(variables);
    const f = variables.filter ?? {};
    const rows = ROWS.filter(
      (p) =>
        (!f.city || p.city.toLowerCase().includes(f.city.toLowerCase())) &&
        (!f.zipCode || p.zipCode === f.zipCode) &&
        (!f.state || p.state === f.state),
    );
    return HttpResponse.json({ data: { __typename: 'Query', properties: rows } });
  });
}

async function setup() {
  const calls: PropertiesQueryVariables[] = [];
  server.use(serveFiltered(calls));
  const user = userEvent.setup();
  renderRoute('/');
  await screen.findByText('1 Main St');
  return { user, calls };
}

describe('property filters', () => {
  it('S3.1 sends the combined filter on Apply and shows only matches', async () => {
    const { user, calls } = await setup();

    await user.type(screen.getByLabelText('City'), '  fountain ');
    await user.selectOptions(screen.getByLabelText('State'), 'AZ');
    await user.click(screen.getByRole('button', { name: 'Apply' }));

    await waitFor(() => expect(screen.queryByText('1 Main St')).not.toBeInTheDocument());
    expect(screen.getByText('15528 E Golden Eagle Blvd')).toBeInTheDocument();
    expect(calls.at(-1)?.filter).toEqual({ city: 'fountain', zipCode: null, state: 'AZ' });
  });

  it('S3.4 sends blank fields as no constraint', async () => {
    const { calls } = await setup();

    expect(calls[0]?.filter).toEqual({ city: null, zipCode: null, state: null });
  });

  it('S3.6 rejects a partial zip code client-side without querying', async () => {
    const { user, calls } = await setup();
    const before = calls.length;

    await user.type(screen.getByLabelText('Zip code'), '852');
    await user.click(screen.getByRole('button', { name: 'Apply' }));

    expect(screen.getByText('Zip code must be exactly 5 digits.')).toBeInTheDocument();
    expect(screen.getByLabelText('Zip code')).toHaveAttribute('aria-invalid', 'true');
    expect(calls).toHaveLength(before);
  });

  it('S3.5 applies an exact zip code with Enter', async () => {
    const { user, calls } = await setup();

    await user.type(screen.getByLabelText('Zip code'), '00901{Enter}');

    await waitFor(() =>
      expect(screen.queryByText('15528 E Golden Eagle Blvd')).not.toBeInTheDocument(),
    );
    expect(calls.at(-1)?.filter?.zipCode).toBe('00901');
  });

  it('S3.8 keeps the filter when the sort order changes', async () => {
    const { user, calls } = await setup();

    await user.selectOptions(screen.getByLabelText('State'), 'PR');
    await user.click(screen.getByRole('button', { name: 'Apply' }));
    await user.click(screen.getByRole('button', { name: /Newest first/ }));

    await screen.findByRole('button', { name: /Oldest first/ });
    expect(calls.at(-1)).toEqual({
      filter: { city: null, zipCode: null, state: 'PR' },
      orderBy: { createdAt: 'ASC' },
    });
  });

  it('S3.10 shows "no matches" and clears the filters from there', async () => {
    const { user, calls } = await setup();

    await user.type(screen.getByLabelText('City'), 'Phoenix');
    await user.click(screen.getByRole('button', { name: 'Apply' }));
    expect(await screen.findByText('No properties match these filters')).toBeInTheDocument();

    await user.click(screen.getByRole('button', { name: 'Clear filters' }));

    expect(await screen.findByText('1 Main St')).toBeInTheDocument();
    expect(screen.getByLabelText('City')).toHaveValue('');
    expect(calls.at(-1)?.filter).toEqual({ city: null, zipCode: null, state: null });
  });
});

import { useState } from 'react';
import { useQuery } from '@apollo/client/react';
import { Link } from 'react-router';
import { ArrowDownUp } from 'lucide-react';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { SortDirection, type PropertiesQuery as PropertiesResult } from '@/gql/graphql';
import { PropertiesQuery } from './properties.query';
import {
  isFiltering,
  NO_FILTER,
  PropertyFilters,
  toPropertyFilter,
  type FilterValues,
} from './property-filters';

type Property = PropertiesResult['properties'][number];

const SORT_LABEL: Record<SortDirection, string> = {
  DESC: 'Newest first',
  ASC: 'Oldest first',
};

const createdAtFormat = new Intl.DateTimeFormat('en-US', {
  dateStyle: 'medium',
  timeStyle: 'short',
});

/** S1 list with the S2 sort toggle and S3 filters. */
export function PropertyList() {
  const [direction, setDirection] = useState<SortDirection>(SortDirection.DESC);
  const [filter, setFilter] = useState<FilterValues>(NO_FILTER);
  const { data, error, loading, refetch } = useQuery(PropertiesQuery, {
    variables: { filter: toPropertyFilter(filter), orderBy: { createdAt: direction } },
    // The list is unmounted while a property is created, so a named refetch would miss it.
    // Showing the cache and re-fetching on every mount keeps it current (S5.8).
    fetchPolicy: 'cache-and-network',
  });
  const properties = data?.properties;

  return (
    <section className="grid gap-4">
      <div className="flex items-center justify-between gap-4">
        <h1 className="font-heading text-2xl font-semibold">Properties</h1>
        <Button
          variant="outline"
          size="sm"
          onClick={() =>
            setDirection((d) => (d === SortDirection.DESC ? SortDirection.ASC : SortDirection.DESC))
          }
          aria-label={`Sorted by creation date: ${SORT_LABEL[direction]}. Change order`}
        >
          <ArrowDownUp />
          {SORT_LABEL[direction]}
        </Button>
      </div>

      <PropertyFilters applied={filter} onApply={setFilter} />

      {error && !properties ? (
        <Alert variant="destructive">
          <AlertTitle>Could not load properties</AlertTitle>
          <AlertDescription className="grid gap-2">
            <span>Check that the API is running, then try again.</span>
            <Button
              variant="outline"
              size="sm"
              className="justify-self-start"
              onClick={() => void refetch()}
            >
              Retry
            </Button>
          </AlertDescription>
        </Alert>
      ) : !properties && loading ? (
        <p className="text-muted-foreground" role="status">
          Loading properties…
        </p>
      ) : properties?.length === 0 && isFiltering(filter) ? (
        <Card>
          <CardContent className="grid justify-items-center gap-2 py-8 text-center">
            <p className="font-medium">No properties match these filters</p>
            <Button variant="outline" size="sm" onClick={() => setFilter(NO_FILTER)}>
              Clear filters
            </Button>
          </CardContent>
        </Card>
      ) : properties?.length === 0 ? (
        <Card>
          <CardContent className="grid gap-2 py-8 text-center">
            <p className="font-medium">No properties yet</p>
            <p className="text-muted-foreground">
              <Link to="/properties/new" className="underline">
                Add a property
              </Link>{' '}
              to record it with its current weather.
            </p>
          </CardContent>
        </Card>
      ) : (
        <ul className="grid gap-3" aria-label="Properties">
          {properties?.map((property) => (
            <li key={property.id}>
              <PropertyRow property={property} />
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

function PropertyRow({ property }: { property: Property }) {
  const description = property.weatherData.weatherDescriptions.join(', ');
  const icon = property.weatherData.weatherIcons[0];
  return (
    <Link
      to={`/properties/${property.id}`}
      className="block rounded-xl ring-1 ring-foreground/10 transition-colors hover:bg-muted/50 focus-visible:outline-2"
    >
      <div className="flex items-center justify-between gap-4 p-4">
        <div className="grid gap-0.5">
          <span className="font-medium">{property.street}</span>
          <span className="text-sm text-muted-foreground">
            {property.city}, {property.state} {property.zipCode}
          </span>
          <span className="text-xs text-muted-foreground">
            Added {createdAtFormat.format(new Date(property.createdAt))}
          </span>
        </div>
        <div className="flex items-center gap-2 text-right">
          {icon && <img src={icon} alt="" className="size-8 rounded" />}
          <div className="grid">
            <span className="font-medium">{property.weatherData.temperature}°F</span>
            <span className="text-xs text-muted-foreground">{description}</span>
          </div>
        </div>
      </div>
    </Link>
  );
}

